-- interview-batch3-diagrams.sql — 面試題庫補圖 批次 3
-- q1 / q4  BJT 四工作區象限圖（同一張圖，兩題共用）
-- q2       NMOS 轉移特性與 VTH
-- q14      邏輯閘真值表
-- q15      NMOS 反相器 + IN/OUT 波形（下降緣瞬時、上升緣帶 RC 斜率）
-- q16      I2C Fast mode 關鍵時序
-- q22      差分對疊構剖面（8px = 1mil，按比例）
--
-- 兩道驗證都過：瀏覽器 getBBox+getCTM 重疊 = 0；語意/幾何斷言全過
--   （真值表 20 格逐格比對布林運算、平方律曲線逐點比對、OUT 波形逐段驗反相、
--     疊構 W/S/H 比例、S/H=1.25 的耦合因子 0.855）
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。冪等，可重跑。

-- q1：BJT 四工作區象限圖（飽和/截止條件）
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="300" viewBox="0 0 520 300" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="300" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">NPN bias: the two junctions decide the region</text><g data-sym="npn"><line x1="124" y1="150" x2="138" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="137" x2="138" y2="163" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="138" y1="145" x2="158" y2="132" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="158" y1="132" x2="158" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="155" x2="158" y2="168" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="158" y1="168" x2="158" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="158,168 150,166 154,160" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/></g><line x1="158" y1="120" x2="158" y2="96" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="164" y="92" fill="#64748b" font-size="11">C</text><line x1="158" y1="180" x2="158" y2="204" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="164" y="212" fill="#64748b" font-size="11">E</text><line x1="124" y1="150" x2="96" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="100" y="142" fill="#64748b" font-size="11">B</text><line x1="84" y1="96" x2="158" y2="96" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><line x1="68" y1="150" x2="96" y2="150" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><line x1="84" y1="96" x2="84" y2="150" stroke="#1f4fd1" stroke-width="1.6" stroke-linecap="round"/><polygon points="80,104 88,104 84,96" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><polygon points="80,142 88,142 84,150" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><text x="78" y="126" fill="#1f4fd1" font-size="11" text-anchor="end" font-weight="bold">VBC</text><line x1="68" y1="204" x2="158" y2="204" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><line x1="68" y1="150" x2="68" y2="204" stroke="#15803d" stroke-width="1.6" stroke-linecap="round"/><polygon points="64,158 72,158 68,150" fill="#15803d" stroke="#15803d" stroke-width="1"/><polygon points="64,196 72,196 68,204" fill="#15803d" stroke="#15803d" stroke-width="1"/><text x="62" y="182" fill="#15803d" font-size="11" text-anchor="end" font-weight="bold">VBE</text><text x="186" y="116" fill="#64748b" font-size="11">BC junction</text><text x="186" y="196" fill="#64748b" font-size="11">BE junction</text><line x1="268" y1="56" x2="268" y2="232" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><text x="282" y="72" fill="#64748b" font-size="11">region</text><text x="430" y="72" fill="#64748b" font-size="11" text-anchor="middle">VBE</text><text x="478" y="72" fill="#64748b" font-size="11" text-anchor="middle">VBC</text><line x1="280" y1="80" x2="508" y2="80" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><text x="282" y="106" fill="#15803d" font-size="11" font-weight="bold">SATURATION</text><text x="282" y="121" fill="#64748b" font-size="11">VCE(sat) = 0.2V</text><text x="430" y="106" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="478" y="106" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="282" y="136" fill="#1f4fd1" font-size="11" font-weight="bold">ACTIVE</text><text x="282" y="151" fill="#64748b" font-size="11">IC = beta x IB</text><text x="430" y="136" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="478" y="136" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="282" y="166" fill="#b91c1c" font-size="11" font-weight="bold">CUTOFF</text><text x="282" y="181" fill="#64748b" font-size="11">IC = 0</text><text x="430" y="166" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="478" y="166" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="282" y="196" fill="#b45309" font-size="11" font-weight="bold">REVERSE ACTIVE</text><text x="282" y="211" fill="#64748b" font-size="11">low gain, rare</text><text x="430" y="196" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="478" y="196" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="10" y="272" fill="#1d2943" font-size="11">fwd = that junction conducts (about 0.7V on silicon). rev = it blocks.</text><text x="10" y="292" fill="#64748b" font-size="11">Saturation needs overdrive too: IB above IC/beta, not just VBE past 0.7V.</text></svg></div>$vsq$ as box) n
 where question like $q$%BJT (NPN) 的飽和%$q$;

-- q2：NMOS 轉移特性與 VTH
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="272" viewBox="0 0 520 272" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="272" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">NMOS: insulated gate, VTH decides ON or OFF</text><g data-sym="nmos"><line x1="90" y1="120" x2="104" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="104" y1="108" x2="104" y2="132" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="111" y1="107" x2="111" y2="133" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="111" y1="112" x2="124" y2="112" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="112" x2="124" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="100" x2="146" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="111" y1="128" x2="124" y2="128" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="128" x2="124" y2="140" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="140" x2="146" y2="140" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="111" y1="120" x2="124" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="117,116 117,124 111,120" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="124" y1="120" x2="124" y2="128" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="140" x2="138" y2="126" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="132,126 144,126 138,114" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="132" y1="114" x2="144" y2="114" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="114" x2="138" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="74" y="110" fill="#64748b" font-size="11" text-anchor="end">G</text><text x="194" y="104" fill="#64748b" font-size="11">D</text><text x="194" y="148" fill="#64748b" font-size="11">S</text><line x1="146" y1="100" x2="190" y2="100" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="146" y1="140" x2="190" y2="140" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="190" y1="140" x2="190" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="190" y1="180" x2="190" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="178" y1="194" x2="202" y2="194" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="182" y1="199" x2="198" y2="199" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="186" y1="204" x2="194" y2="204" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="90" y1="120" x2="60" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="60" y1="120" x2="40" y2="120" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><line x1="40" y1="180" x2="190" y2="180" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><line x1="40" y1="120" x2="40" y2="180" stroke="#b45309" stroke-width="1.6" stroke-linecap="round"/><polygon points="36,128 44,128 40,120" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="36,172 44,172 40,180" fill="#b45309" stroke="#b45309" stroke-width="1"/><text x="48" y="154" fill="#b45309" font-size="11" font-weight="bold">VGS</text><line x1="270" y1="60" x2="270" y2="200" stroke="#94a3b8" stroke-width="1.4" stroke-linecap="round"/><line x1="270" y1="200" x2="500" y2="200" stroke="#94a3b8" stroke-width="1.4" stroke-linecap="round"/><polyline points="270,200 280,200 290,200 300,200 310,200 320,200 330,200 340,200 340,200.0 350,199.3 360,197.3 370,194.0 380,189.4 390,183.4 400,176.1 410,167.5 420,157.6 430,146.3 440,133.7 450,119.7 460,104.5 470,87.9 480,70.0" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="340" y1="80" x2="340" y2="200" stroke="#b91c1c" stroke-width="1.2" stroke-linecap="round"/><text x="264" y="56" fill="#64748b" font-size="11" text-anchor="end">ID</text><text x="500" y="220" fill="#64748b" font-size="11" text-anchor="end">VGS</text><text x="344" y="220" fill="#b91c1c" font-size="11">VTH</text><text x="276" y="120" fill="#b91c1c" font-size="11">OFF: ID = 0</text><text x="350" y="96" fill="#15803d" font-size="11">ID = k (VGS-VTH)^2</text><text x="10" y="244" fill="#1d2943" font-size="11">Gate plate and channel never touch - that gap is the oxide, so IG is ~pA.</text><text x="10" y="264" fill="#64748b" font-size="11">The body diode comes with the FET. VTH is no hard wall: below it the device still leaks.</text></svg></div>$vsq$ as box) n
 where question like $q$%NMOSFET 的開啟%$q$;

-- q4：BJT 四工作區（與 q1 同圖）
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
