="middle">rev</text><text x="478" y="166" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="282" y="196" fill="#b45309" font-size="11" font-weight="bold">REVERSE ACTIVE</text><text x="282" y="211" fill="#64748b" font-size="11">low gain, rare</text><text x="430" y="196" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="478" y="196" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="10" y="272" fill="#1d2943" font-size="11">fwd = that junction conducts (about 0.7V on silicon). rev = it blocks.</text><text x="10" y="292" fill="#64748b" font-size="11">Saturation needs overdrive too: IB above IC/beta, not just VBE past 0.7V.</text></svg></div>$vsq$ as box) n
 where question like $q$%BJT 的四種工作區域%$q$;

-- q14：邏輯閘真值表
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="228" viewBox="0 0 520 228" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="228" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Logic Gate Truth Table</text><line x1="45" y1="72" x2="495" y2="72" stroke="#888" stroke-width="1.4"/><line x1="152" y1="46" x2="152" y2="200" stroke="#334155" stroke-width="1.4"/><text x="70" y="62" fill="#ffc107" font-size="12" font-weight="bold" text-anchor="middle">A</text><text x="120" y="62" fill="#ffc107" font-size="12" font-weight="bold" text-anchor="middle">B</text><text x="195" y="62" fill="#00d4ff" font-size="12" font-weight="bold" text-anchor="middle">AND</text><text x="258" y="62" fill="#00d4ff" font-size="12" font-weight="bold" text-anchor="middle">OR</text><text x="325" y="62" fill="#00d4ff" font-size="12" font-weight="bold" text-anchor="middle">NAND</text><text x="395" y="62" fill="#00d4ff" font-size="12" font-weight="bold" text-anchor="middle">NOR</text><text x="460" y="62" fill="#00d4ff" font-size="12" font-weight="bold" text-anchor="middle">XOR</text><text x="70" y="100" fill="#ffc107" font-size="12" text-anchor="middle">0</text><text x="120" y="100" fill="#ffc107" font-size="12" text-anchor="middle">0</text><text x="195" y="100" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="258" y="100" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="325" y="100" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="395" y="100" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="460" y="100" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="70" y="126" fill="#ffc107" font-size="12" text-anchor="middle">0</text><text x="120" y="126" fill="#ffc107" font-size="12" text-anchor="middle">1</text><text x="195" y="126" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="258" y="126" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="325" y="126" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="395" y="126" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="460" y="126" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="70" y="152" fill="#ffc107" font-size="12" text-anchor="middle">1</text><text x="120" y="152" fill="#ffc107" font-size="12" text-anchor="middle">0</text><text x="195" y="152" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="258" y="152" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="325" y="152" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="395" y="152" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="460" y="152" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="70" y="178" fill="#ffc107" font-size="12" text-anchor="middle">1</text><text x="120" y="178" fill="#ffc107" font-size="12" text-anchor="middle">1</text><text x="195" y="178" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="258" y="178" fill="#c8d4ee" font-size="12" text-anchor="middle">1</text><text x="325" y="178" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="395" y="178" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="460" y="178" fill="#c8d4ee" font-size="12" text-anchor="middle">0</text><text x="10" y="220" fill="#888" font-size="11">NAND and NOR are universal gates. XOR = 1 when the inputs differ.</text></svg></div>$vsq$ as box) n
 where question like $q$%請填寫以下邏輯閘的真值表%$q$;

-- q15：NMOS 反相器 + IN/OUT 波形
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="300" viewBox="0 0 520 300" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="300" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">NMOS inverter: FET pulls down, resistor pulls up</text><g data-sym="rail"><line x1="146" y1="66" x2="146" y2="78" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="66" x2="154" y2="66" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="156" y="72" fill="#b91c1c" font-size="11" font-weight="bold">5V</text><g data-sym="resistor"><line x1="146" y1="86" x2="146" y2="98" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="146,98 139,101 153,107 139,113 153,119 146,122" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="146" y1="122" x2="146" y2="134" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="158" y="106" fill="#64748b" font-size="11">10k</text><line x1="146" y1="78" x2="146" y2="86" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="146" y1="134" x2="146" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="146" cy="150" r="2.6" fill="#1f4fd1"/></g><line x1="146" y1="150" x2="206" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="212" y="154" fill="#1d2943" font-size="11" font-weight="bold">OUT</text><g data-sym="nmos"><line x1="90" y1="190" x2="104" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="104" y1="178" x2="104" y2="202" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="111" y1="177" x2="111" y2="203" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="111" y1="182" x2="124" y2="182" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="182" x2="124" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="170" x2="146" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="111" y1="198" x2="124" y2="198" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="198" x2="124" y2="210" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="210" x2="146" y2="210" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="111" y1="190" x2="124" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="117,186 117,194 111,190" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="124" y1="190" x2="124" y2="198" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="210" x2="138" y2="196" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="132,196 144,196 138,184" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="132" y1="184" x2="144" y2="184" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="184" x2="138" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="146" y1="170" x2="146" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="146" y1="210" x2="146" y2="230" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="146" y1="230" x2="146" y2="244" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="134" y1="244" x2="158" y2="244" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="249" x2="154" y2="249" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="142" y1="254" x2="150" y2="254" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="90" y1="190" x2="40" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="34" y="194" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">IN</text><text x="276" y="92" fill="#b45309" font-size="11" text-anchor="end" font-weight="bold">IN</text><polyline points="284,100 320,100 320,74 374,74 374,100 428,100 428,74 494,74" fill="none" stroke="#b45309" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="276" y="172" fill="#1f4fd1" font-size="11" text-anchor="end" font-weight="bold">OUT</text><polyline points="284,154 320,154 320,180 374,180 386,154 428,154 428,180 494,180" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="392" y="140" fill="#b91c1c" font-size="11">slow rise: 10k x Cload</text><text x="10" y="272" fill="#1d2943" font-size="11">IN low -> FET off -> OUT pulled to 5V. IN high -> FET on -> OUT ~0V.</text><text x="10" y="292" fill="#64748b" font-size="11">Static current 5V/10k = 0.5mA while on. Fall is FET-driven, rise is resistor-only.</text></svg></div>$vsq$ as box) n
 where question like $q$%上方接 10KΩ 上拉到 5V%$q$;

-- q16：I2C Fast mode 關鍵時序
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="252" viewBox="0 0 520 252" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="252" fill="#0a0a1a"/><text x="260" y="20" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">I2C Fast Mode (400kHz) Key Timings</text><path d="M70,120 L100,80 H220 L250,120 H320 L350,80 H450" fill="none" stroke="#00d4ff" stroke-width="2"/><text x="64" y="104" fill="#00d4ff" font-size="11" text-anchor="end">SCL</text><line x1="70" y1="140" x2="100" y2="140" stroke="#00ff88" stroke-width="1.4"/><text x="85" y="136" fill="#00ff88" font-size="11" text-anchor="middle">tr</text><line x1="220" y1="140" x2="250" y2="140" stroke="#00ff88" stroke-width="1.4"/><text x="235" y="136" fill="#00ff88" font-size="11" text-anchor="middle">tf</text><line x1="100" y1="152" x2="220" y2="152" stroke="#ffc107" stroke-width="1.4"/><text x="160" y="146" fill="#ffc107" font-size="11" text-anchor="middle">tHIGH &gt;= 0.6us</text><line x1="250" y1="170" x2="320" y2="170" stroke="#ffc107" stroke-width="1.4"/><text x="285" y="164" fill="#ffc107" font-size="11" text-anchor="middle">tLOW &gt;= 1.3us</text><text x="360" y="140" fill="#00ff88" font-size="11">tr, tf &lt;= 300ns</text><path d="M70,210 H280 V180 H450" fill="none" stroke="#ffc107" stroke-width="2"/><text x="64" y="196" fill="#ffc107" font-size="11" text-anchor="end">SDA</text><line x1="320" y1="176" x2="320" y2="216" stroke="#ff6b6b" stroke-width="1" stroke-dasharray="3"/><line x1="280" y1="224" x2="320" y2="224" stroke="#ff6b6b" stroke-width="1.4"/><text x="300" y="240" fill="#ff6b6b" font-size="11" text-anchor="middle">tSU;DAT &gt;= 100ns</text><text x="360" y="212" fill="#888" font-size="11">tHD;DAT &gt;= 0</text></svg></div>$vsq$ as box) n
 where question like $q$%I2C Fast Mode 規格中%$q$;

-- q22：差分對疊構剖面（按比例）
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="224" viewBox="0 0 520 224" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="224" fill="#0a0a1a"/><text x="260" y="20" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Differential Pair Cross-Section (to scale, 8px = 1mil)</text><rect x="80" y="100" width="360" height="32" fill="none" stroke="#334155" stroke-width="1.6"/><text x="330" y="120" fill="#c8d4ee" font-size="11" text-anchor="middle">FR-4  er = 4.2</text><rect x="180" y="90" width="40" height="10" fill="#ffc107"/><rect x="260" y="90" width="40" height="10" fill="#ffc107"/><rect x="80" y="132" width="360" height="10" fill="#4b5563"/><text x="200" y="82" fill="#ffc107" font-size="11" text-anchor="middle">W=5</text><text x="240" y="66" fill="#00ff88" font-size="11" text-anchor="middle">S=5</text><text x="280" y="82" fill="#ffc107" font-size="11" text-anchor="middle">W=5</text><line x1="240" y1="72" x2="240" y2="88" stroke="#00ff88" stroke-width="1.2"/><line x1="150" y1="100" x2="150" y2="132" stroke="#00d4ff" stroke-width="1.4"/><text x="144" y="120" fill="#00d4ff" font-size="11" text-anchor="end">H=4</text><text x="86" y="158" fill="#888" font-size="11">solid GND plane (return path)</text><text x="10" y="186" fill="#c8d4ee" font-size="11">Zdiff = 2 x Zo x (1 - 0.48 x exp(-0.96 x S/H))   [mils]</text><text x="10" y="206" fill="#888" font-size="11">Coupling rises as S/H falls. Keep the pair on one layer over solid GND.</text></svg></div>$vsq$ as box) n
 where question like $q$%差分阻抗設計%$q$;

-- 驗收：七列的 zh / en 都要 t
select left(question, 22) as q,
       answer like '%<svg%' as zh, answer_en like '%<svg%' as en,
       answer_ja like '%<svg%' as ja, answer_ko like '%<svg%' as ko
  from public.interview_questions
 where question like $q$%BJT (NPN) 的飽和%$q$
    or question like $q$%NMOSFET 的開啟%$q$
    or question like $q$%BJT 的四種工作區域%$q$
    or question like $q$%請填寫以下邏輯閘的真值表%$q$
    or question like $q$%上方接 10KΩ 上拉到 5V%$q$
    or question like $q$%I2C Fast Mode 規格中%$q$
    or question like $q$%差分阻抗設計%$q$;
